import {cases,profiles} from './content.mjs';
import {competencies,analyzeJD,makeCase} from './adapt.mjs';
import {buildFeedback} from './feedback.mjs';
import {councilTopics,createCouncil,councilView,councilAct} from './council.mjs';
import {councilMarkup,councilEntry} from './council-view.mjs';
import {newCouncilChat,submitCouncilMessage,confirmCouncilMessage,councilChatMarkup} from './council-chat.mjs';
const app=document.querySelector('#app');
const state={councilChat:null,council:null,councilOrigin:'general',view:'home',mode:'general',caseId:'general',jd:'',role:'ui',matches:[],stage:'investigate',opened:new Set(),asked:new Set(),choice:null,firstChoice:null,note:'',revision:'',history:[],level:'PM',origin:'general',analysis:null,selected:[],activeCase:null,activeSkill:null,openedBefore:[],attempt:null,rehearsal:'',rehearsalResult:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roleLabels={general:'Cross-functional PM',ui:'UI / UX PM',adas:'ADAS PM',platform:'Platform / technical PM',growth:'Growth PM'};
const currentCase=()=>state.activeCase||cases[state.caseId];
const arrow='<span aria-hidden="true">↗</span>';
const icon='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 6 12 11 16 4 20 11 29 6 26 22 16 29 6 22Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="m8 14 6 4-4 3m14-7-6 4 4 3" fill="none" stroke="currentColor" stroke-width="2"/></svg>';
function button(label,action,cls='button',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function go(view){state.view=view;render();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
function nav(){return `<header class="site-header"><button class="brand" data-action="home" aria-label="Stakewolf home">${icon}stakewolf</button><nav aria-label="Main navigation">${button('Practice','general','navlink'+(state.mode==='general'&&state.view!=='home'?' active':''))}${button('Interview prep','jd','navlink'+(state.mode==='interview'&&state.view!=='home'?' active':''))}${button('Your activity','activity','navlink')}</nav><span class="preview-tag"><i></i> DESIGN PREVIEW</span></header>`;}
function footer(){return `<footer><span class="foot-brand">STAKEWOLF / LEARN TO QUESTION.</span><span>Local practice engine · no live AI · progress clears on refresh</span></footer>`;}
function header(kicker,title,desc){return `<div class="page-heading"><p class="eyebrow">${kicker}</p><h1 tabindex="-1">${title}</h1><p class="lede">${desc}</p></div>`;}
function home(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="small-star">✳</span> THE PRODUCT MINDSET, PUT TO PRACTICE</p><h1 tabindex="-1">Good judgment.<br><em>Practised.</em></h1><p class="lede">Ask sharper questions. See what others miss.<br>Build the thinking behind your next great move.</p><div class="hero-tags"><span>Product sense</span><span>Technical reasoning</span><span>Evidence & influence</span></div></div><div class="evidence-art" aria-label="Illustrative conflicting evidence: conversion up 18 percent, complaint volume up 50 percent. Which question would you ask first?"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-caption">A CLAIM IS A STARTING POINT.</span><div class="art-card card-back"><span class="eyebrow">02 / SUPPORT SNAPSHOT</span><strong>+50<span>%</span></strong><p>More complaints.<br>More traffic, too.</p><span class="tiny">What changed in the rate?</span></div><div class="art-card card-front"><span class="eyebrow">01 / EXPERIMENT BRIEF</span><strong>+18<span>%</span></strong><p>Conversion is up.<br>For <u>which users?</u></p><div class="sparkline"><svg viewBox="0 0 250 44" aria-hidden="true"><path d="M0 39 35 32 62 35 94 19 130 25 160 10 193 16 225 5 250 9" fill="none" stroke="currentColor" stroke-width="2"/></svg></div><span class="tiny">Illustrative practice evidence</span></div><div class="art-stamp">LOOK<br><em>closer.</em>${arrow}</div></div></section><section class="entry-section" aria-labelledby="choose-path"><div class="section-line"><h2 id="choose-path">Where do you want to go?</h2><span>ONE MINDSET. TWO WAYS IN.</span></div><div class="entry-grid"><button class="entry-card practice-entry" data-action="general"><div class="entry-top"><span class="eyebrow">01 / GENERAL PRACTICE</span><span class="circle-arrow">↗</span></div><h3>Build your<br><em>PM instincts.</em></h3><p>Explore a skill. Investigate a claim.<br>Make a decision you can stand behind.</p><div class="entry-bottom"><span>Choose your next challenge</span><span>→</span></div></button><button class="entry-card interview-entry" data-action="jd"><div class="entry-top"><span class="eyebrow">02 / INTERVIEW PREPARATION</span><span class="circle-arrow">↗</span></div><h3>A specific role.<br><em>A focused path.</em></h3><p>Bring the job description.<br>See what to practise, and why it matters.</p><div class="entry-bottom"><span>Build your preparation path</span><span>→</span></div></button></div></section>${councilEntry(councilTopics)}<section class="method"><div><p class="eyebrow">THE STAKEWOLF APPROACH</p><h2>Everyone has a view.<br><em>Find your footing.</em></h2></div><div class="method-steps"><div><b>01</b><span><strong>Investigate</strong>Ask what a confident claim leaves out.</span></div><div><b>02</b><span><strong>Make your move</strong>Commit to a recommendation. Hear the pushback.</span></div><div><b>03</b><span><strong>Reflect & repeat</strong>Revisit your evidence, assumptions and next question.</span></div></div></section>`;}
function general(){return `${header('THE PRACTICE ROOM','Choose your <em>next edge.</em>','Try a two-round council with negotiated commitments, or start with a shorter guided exercise.')}${councilEntry(councilTopics)}<div class="round-grid">${Object.entries(cases).map(([id,c],i)=>`<article class="round-card"><div class="round-art round-art-${i}" aria-hidden="true">${i===0?'<span class="graphic-num">18<small>%</small></span><span class="graphic-label">THE WHOLE PICTURE?</span>':i===1?'<div class="flow-box">01</div><div class="flow-line"></div><div class="flow-box">?</div>':'<div class="scope-ring"><span>DEFINED<br>SCOPE</span></div>'}</div><div class="round-body"><p class="eyebrow">0${i+1} / ${esc(c.tag)}</p><h2>${esc(c.skill)}</h2><p>${esc(c.intro)}</p><span class="meta">${id==='adas'?'Interface sample · not expert assessment':c.duration+' · guided preview'}</span>${button('Explore this round '+arrow,'start','button full',`data-case="${id}"`)}</div></article>`).join('')}</div><p class="quiet-note">This preview uses prepared questions and evidence. It demonstrates the journey; it does not grade your PM ability.</p>`;}
function jd(){return `${header('YOUR NEXT OPPORTUNITY','Bring the role.<br><em>Find your focus.</em>','Start with a job description. Review the relevant skills, then step into a practice round.')}<div class="jd-layout"><section class="surface jd-input"><div class="section-line"><h2>The job description</h2><span class="tiny">TEXT ONLY IN THIS PREVIEW</span></div><div class="sample-buttons"><span>Try a sample</span>${button('UI / UX role','sample','chip','data-role="ui"')}${button('ADAS role','sample','chip','data-role="adas"')}${button('Platform role','sample','chip','data-role="platform"')}</div><label for="jd-text">Paste a job description</label><textarea id="jd-text" name="jd" rows="9" maxlength="6000" placeholder="Role, responsibilities, skills…">${esc(state.jd)}</textarea><div class="form-bottom"><label for="level">Target level<select id="level"><option ${state.level==='Associate'?'selected':''}>Associate</option><option ${state.level==='PM'?'selected':''}>PM</option><option ${state.level==='Senior'?'selected':''}>Senior</option></select></label>${button('Build my preparation path '+arrow,'build-path','button dark','id="build-path"'+(state.jd.trim()?'':' disabled'))}</div><p class="privacy-note">Your text stays in this tab. A local rules engine selects from six authored skill modules using the responsibilities it recognises. You can correct the matches. Level changes the question emphasis; it is not calibrated difficulty. No AI service receives your JD.</p>${button('Clear description','clear-jd','text-button')}</section><aside class="path-explainer"><span class="eyebrow">FROM OPPORTUNITY TO PRACTICE</span><h2>A little more<br><em>intentional.</em></h2><ol><li><b>Make the role clear</b><p>Check the suggested focus. You can change it.</p></li><li><b>See a preparation path</b><p>Connect skills to a relevant practice round.</p></li><li><b>Try your thinking</b><p>Explore evidence, take a position and reflect.</p></li></ol><span class="outline-badge">NO ACCOUNT REQUIRED FOR THIS PREVIEW</span></aside></div>`;}
function path(){
  const analysis=state.analysis||{matches:[],roles:[],warnings:[]};
  return `${header('INTERVIEW PREPARATION / YOUR JD, YOUR FOCUS','A role is more<br><em>than its title.</em>','Review the responsibilities we found. Choose the skills to practise, then enter a room where each stakeholder has a different reason to persuade you.')}<div class="plan-layout"><aside class="role-card"><span class="eyebrow">CONFIRM THE CONTEXT</span><label for="role-select">Role context<select id="role-select">${Object.entries(roleLabels).map(([id,label])=>`<option value="${id}" ${state.role===id?'selected':''}>${label}</option>`).join('')}</select></label><h2>${roleLabels[state.role]}</h2><span class="outline-badge">${esc(state.level)} · local adaptation</span><div class="role-divider"></div><p class="small">${analysis.roles.some(r=>r.id!=='general')?'Detected context: '+analysis.roles.filter(r=>r.id!=='general').map(r=>esc(r.label)).join(', ')+'. You can override it above.':'No supported role detected. Choose the role context manually.'} Role context changes the interview framing. The selected responsibility determines the fictional exercise.</p><div class="role-divider"></div><p class="eyebrow">SELECT RESPONSIBILITIES</p><div class="skill-options">${competencies.map(c=>`<label><input type="checkbox" name="skill" value="${c.id}" ${state.selected.includes(c.id)?'checked':''}><span>${esc(c.label)}<small>${analysis.matches.some(m=>m.id===c.id)?'Found in JD':'Add manually'}</small></span></label>`).join('')}</div>${button('Edit job description','jd','text-button light')}</aside><section><div class="section-line"><h2>Your preparation rounds</h2><span>${state.selected.length} SELECTED</span></div>${!analysis.matches.length?'<p class="notice">No supported responsibilities found. Nothing has been selected for you. Choose a skill manually, or edit the JD with more specific responsibilities.</p>':''}${analysis.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<div class="adaptive-rounds">${state.selected.map((id,i)=>{const match=analysis.matches.find(m=>m.id===id);const c=makeCase(id,{level:state.level,role:state.role});return `<article class="adaptive-card"><p class="eyebrow">${String(i+1).padStart(2,'0')} / ${esc(c.skill)}</p><h2>${esc(c.title).replace('\n','<br>')}</h2><div class="jd-source"><span class="eyebrow">${match?'WHY THIS IS IN YOUR PATH':'MANUALLY ADDED'}</span><p>${match?match.evidence.map(x=>esc(x)).join(' · '):'You selected this skill; it was not inferred from your description.'}</p></div><h3>Questions to prepare for</h3><ol class="interview-prompts">${c.interviewQuestions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><p class="small">${esc(c.intro)}</p><div class="round-bottom"><span class="tiny">3 stakeholders · 2 questions · hidden incentives</span>${button('Enter this discussion '+arrow,'start-adaptive','button dark',`data-skill="${id}"`)}</div>${['accessibility','systems'].includes(id)?`<div class="council-inline-entry"><p>Take this skill into two connected rounds: negotiate support, reserve work and live with the consequences.</p>${button('Try the two-round council →','start-council','button dark',`data-topic="${id}"`)}</div>`:''}</article>`;}).join('')}</div>${state.selected.length?'':'<div class="surface empty-state"><h2>Choose your first focus.</h2><p>Select a responsibility to build a practice round.</p></div>'}<p class="quiet-note">These are authored practice questions selected locally, not predictions of an employer’s interview. Domains beyond the six modules need manual selection. Technical examples require expert validation before assessment use.</p></section></div>`;
}
function session(){let c=currentCase();const challenge=state.stage==='challenge';return `<div class="session-top">${button('← '+(state.mode==='interview'?'Preparation path':'Practice room'),'back-practice','text-button')}<span class="eyebrow">${esc(c.tag)} · ${challenge?'02 / RESPOND':'01 / INVESTIGATE'}</span><span class="outline-badge">GUIDED PREVIEW</span></div><div class="session-heading"><div><h1 tabindex="-1">${esc(c.title).replace('\n','<br>')}</h1><p class="lede">${esc(c.intro)}</p></div><div class="round-marker"><span>${challenge?'02':'01'}</span><small>OF 03</small></div></div>${(state.caseId==='adas'||state.activeSkill==='validation')?'<p class="notice">Illustrative ADAS content for owner design review. Not expert-validated or a safety assessment.</p>':''}${state.activeCase?`<div class="notice"><strong>Question carefully.</strong> ${challenge?'The questioning phase is complete. Respond to the new evidence.':`You can ask ${Math.max(0,2-state.asked.size)} more stakeholder questions before deciding.`} Open any evidence record. Private incentives are revealed afterwards; disagreement alone does not prove dishonesty.</div><details class="prompt-panel"><summary>Your role-specific interview prompts</summary><ol>${c.interviewQuestions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></details>`:''}<div class="workspace"><section class="conversation surface"><div class="section-line"><h2>${challenge?'A new piece of the picture':state.activeCase?'Three views. One decision.':'Two views. One decision.'}</h2><span>${challenge?'NEW EVIDENCE':'LISTEN & QUESTION'}</span></div>${challenge?`<div class="new-evidence"><span class="eyebrow">UPDATE / AFTER YOUR RECOMMENDATION</span><p>${esc(c.update)}</p></div>${state.activeCase?`<div class="consequence"><span class="eyebrow">RESULT OF YOUR FIRST DECISION</span><p>${esc(c.choices[state.firstChoice].outcome)}</p></div>`:''}<div class="committed"><span class="tiny">YOUR FIRST POSITION</span><strong>${esc(c.choices[state.firstChoice].title)}</strong><p>${esc(state.note)||'No reasoning note added.'}</p></div><h3>Would you change your position?</h3><p class="small">Updating an answer can be good judgment. Explain what the new evidence changes.</p>`:c.people.map((p,i)=>`<article class="speaker"><div class="speaker-head"><span class="avatar">${p.initial}</span><div><h3>${esc(p.name)}</h3><span>${esc(p.aim)}</span></div></div><blockquote>${esc(p.claim)}</blockquote>${state.asked.has(i)?`<div class="reply" data-reply="${i}" tabindex="-1"><span class="eyebrow">YOU ASKED / ${esc(p.question)}</span><p>${esc(p.answer)}</p><span class="tiny">Related record: ${esc(p.source)}</span></div>`:button(p.question+' →','ask','question-button',`data-index="${i}" ${state.activeCase&&state.asked.size>=2?'disabled':''}`)}</article>`).join('')}<div class="decision-block"><p class="eyebrow">${challenge?'RECONSIDER':'YOUR NEXT MOVE'}</p><h3>${challenge?'Choose your updated recommendation.':esc(c.question)}</h3><fieldset class="choices"><legend class="sr-only">Your recommendation</legend>${c.choices.map((d,i)=>`<label class="choice ${state.choice===i?'selected':''}"><input type="radio" name="decision" value="${i}" ${state.choice===i?'checked':''}><span><strong>${esc(d.title)}</strong><small>${esc(d.detail)}</small></span><span class="choice-dot"></span></label>`).join('')}</fieldset><label for="reasoning">${challenge?'What changed your thinking?':'Your reasoning'} <span class="optional">Optional · kept only in this tab</span></label><textarea id="reasoning" aria-describedby="reasoning-hint" rows="3" maxlength="1800" placeholder="I would… because… The assumption I would check is…">${esc(challenge?state.revision:state.note)}</textarea><p class="tiny" id="reasoning-hint">For traceable coaching, name the records and stakeholder roles you use. Explain what they support and what remains uncertain; the coach checks wording, not correctness.</p><div class="decision-actions"><span class="tiny">${challenge?'Your answer gets local coaching, with no ability score.':'Choose a position to continue.'}</span>${button(challenge?'Review my answer →':'Commit & see what changes →',challenge?'finish':'commit','button dark','id="decision-submit"'+(state.choice===null?' disabled':''))}</div></div></section><aside class="evidence-rail"><div class="section-line"><h2>On the record</h2><span>${state.opened.size}/${c.evidence.length} OPENED</span></div><p class="small">Claims are invitations to investigate.<br>Open a source before choosing a side.</p>${c.evidence.map((e,i)=>`<details class="evidence-record" data-record="${e.id}" ${state.opened.has(e.id)?'open':''}><summary><span class="eyebrow">0${i+1} / ${e.kind}</span><strong>${esc(e.name)}</strong><span class="record-arrow">+</span></summary><div><h3>${esc(e.title)}</h3><p>${esc(e.detail)}</p></div></details>`).join('')}<div class="field-note"><span class="eyebrow">A THOUGHT TO TAKE WITH YOU</span><p>“What would I need to know to change my mind?”</p></div><p class="tiny">Fictional sample evidence. Prepared replies. No live AI or ability score.</p></aside></div>`;}
function captureOpened(){document.querySelectorAll('[data-record][open]').forEach(el=>state.opened.add(el.dataset.record));}
function answerSignals(analysis){
  const references=analysis.references.filter(r=>r.status==='detected');
  return `<p class="small">${esc(analysis.notice)}</p>${analysis.hasText?`<blockquote class="answer-excerpt">${esc(analysis.text)}</blockquote>`:'<p class="empty-answer">No answer written for this stage. Add a rehearsal below to try the coaching.</p>'}<p class="small"><b>Names found:</b> ${references.length?references.map(r=>esc(r.name)).join(', '):'No explicit record or stakeholder names detected.'}</p><div class="signal-list">${analysis.cues.map(cue=>`<article><div><h4>${esc(cue.label)}</h4><span class="signal-status">${cue.status==='detected'?'Wording found':'Not detected'}</span></div>${cue.excerpts.length?`<p class="match-excerpt">${cue.excerpts.map(x=>`“${esc(x)}”`).join(' · ')}</p>`:''}</article>`).join('')}</div><p class="tiny">Wording found is a prompt for self-review, not proof of good reasoning. A paraphrase may be missed.</p>`;
}
function feedbackPanel(c){
  if(!state.attempt)return '';
  const f=buildFeedback(c,state.attempt);
  const phrase=(mention)=>mention.status==='detected'?`Name referenced: ${mention.excerpts.map(x=>`“${esc(x)}”`).join(' · ')}`:'Name not detected; you may have paraphrased it.';
  return `<section class="answer-feedback" aria-labelledby="feedback-title"><div class="feedback-heading"><div><p class="eyebrow">YOUR ANSWER / LOCAL COACHING</p><h2 id="feedback-title">Make your reasoning<br><em>easier to defend.</em></h2></div><span class="outline-badge">NO SCORE. NO API CALLS.</span></div><p class="feedback-intro">We can check what you explored and highlight wording in your answer. We cannot reliably judge whether your argument is correct or persuasive. Use these specific prompts to review it.</p><div class="feedback-grid"><section class="feedback-priorities"><p class="eyebrow">YOUR NEXT IMPROVEMENTS</p><ol>${f.nextSteps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>A question for your chosen approach</h3><p>${esc(f.decision.prompt)}</p></section><section class="answer-structure"><p class="eyebrow">TRY THIS INTERVIEW STRUCTURE</p><ol>${f.scaffold.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="tiny">A structure to fill in, not a model answer or an employer’s scoring rubric.</p></section></div><div class="feedback-section"><h3>01 / Evidence you may have missed</h3><p class="small">All records below were available before your first decision. Opening is an action, not proof of understanding. Stakeholder replies can also contain record information.</p><div class="feedback-records">${f.records.map(r=>`<article><span class="coverage-label">${r.openedBefore?'Opened before deciding':r.openedAfter?'Opened after deciding':'Not opened'}${r.consultedViaReply?' · Related stakeholder questioned':''}</span><h4>${esc(r.name)}</h4><p>${esc(r.detail)}</p><dl><dt>First answer</dt><dd>${phrase(r.firstMention)}</dd><dt>Final answer</dt><dd>${phrase(r.finalMention)}</dd></dl><p class="coach-prompt">${esc(r.prompt)}</p></article>`).join('')}</div></div><div class="feedback-section"><h3>02 / How you handled the competing views</h3><p class="small">A stakeholder name is only a reference. Explain their legitimate concern, where the evidence limits their claim, and the trade-off you propose. You were not expected to know their private incentive.</p><div class="feedback-views">${f.views.map(v=>`<article><span class="coverage-label">${v.contacted?'You asked a follow-up':'No follow-up asked'}</span><h4>${esc(v.name)}</h4><p>${esc(v.aim)}</p><blockquote>${esc(v.claim)}</blockquote>${v.response?`<details class="heard-reply"><summary>The reply you received</summary><p class="small">${esc(v.response)}</p><p class="tiny">Related record: ${esc(v.source)}</p></details>`:''}<details><summary>Compare with your answers</summary><p class="small"><b>First:</b> ${phrase(v.firstMention)}</p><p class="small"><b>Final:</b> ${phrase(v.finalMention)}</p></details><p class="coach-prompt">${esc(v.prompt)}</p></article>`).join('')}</div><p class="tiny">${state.activeCase?'The two-question budget means one stakeholder will remain unasked. This is a trade-off to explain, not an automatic mistake.':'Follow-up counts describe activity, not competence.'}</p></div><div class="feedback-section"><h3>03 / Turn the answer into an interview response</h3><div class="answer-comparison"><details><summary>Your first answer — before the update</summary>${answerSignals(f.first)}</details><details open><summary>Your final answer — after the update</summary>${answerSignals(f.final)}</details></div><div class="update-coaching"><span class="eyebrow">NEW INFORMATION / FINAL ANSWER ONLY</span><p>${esc(f.update.detail)}</p><p class="coach-prompt">${esc(f.update.prompt)}</p></div></div><section class="rehearsal-box"><p class="eyebrow">ONE MORE TRY / REHEARSAL</p><h3>Say it more clearly.</h3><p class="small">Rewrite your final explanation using the prompts. This does not alter your original decisions, answers or activity. Everything clears on refresh.</p><label for="rehearsal-answer">Your improved interview answer</label><textarea id="rehearsal-answer" rows="5" maxlength="1800" placeholder="My recommendation is… The evidence supports… The competing concern is… I would verify…">${esc(state.rehearsal)}</textarea><div class="rehearsal-actions">${button('Check my rehearsal →','rehearse','button dark')}${button('Clear rehearsal','reset-rehearsal','text-button')}</div>${state.rehearsalResult!==null?`<div id="rehearsal-feedback" tabindex="-1" role="region" aria-label="Rehearsal feedback"><h4>Rehearsal signals — original attempt preserved</h4>${answerSignals(buildFeedback(c,{...state.attempt,rehearsal:state.rehearsalResult}).final)}<p class="small">Revisit the evidence and competing views above to check whether each statement is supported.</p></div>`:''}</section><details class="feedback-limits"><summary>How this feedback works & where it can be wrong</summary><ul>${f.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>If a finding misses your phrasing, treat it as a suggestion you can reject. There is no saved score or penalty.</p></details></section>`;
}

function review(){let c=currentCase();return `${header('03 / REFLECT','A decision is only<br><em>part of the story.</em>','Here is the path you took. Review the evidence you explored and the signals in your answer. Use the coaching prompts to make your next explanation more specific.')}${feedbackPanel(c)}<details class="original-trace"><summary>Revisit your original decision & consequences</summary><div class="review-layout"><section><div class="trace-metrics"><div><strong>${state.asked.size}<small>/${state.activeCase?2:c.people.length}</small></strong><span>Questions asked</span></div><div><strong>${state.opened.size}<small>/${c.evidence.length}</small></strong><span>Records opened</span></div><div><strong>${state.choice===state.firstChoice?'Held':'Revised'}</strong><span>Your recommendation</span></div></div><div class="timeline"><article><span>01</span><div><p class="eyebrow">YOUR FIRST POSITION</p><h3>${esc(c.choices[state.firstChoice].title)}</h3><p class="quoted">${esc(state.note)||'You did not add a reasoning note.'}</p></div></article><article><span>02</span><div><p class="eyebrow">THE NEW EVIDENCE</p><p>${esc(c.update)}</p>${state.activeCase?`<p><strong>Consequence of your first choice:</strong> ${esc(c.choices[state.firstChoice].outcome)}</p>`:''}</div></article><article><span>03</span><div><p class="eyebrow">YOUR FINAL POSITION</p><h3>${esc(c.choices[state.choice].title)}</h3><p class="quoted">${esc(state.revision)||'You did not add a revision note.'}</p></div></article></div></section><aside class="reflection"><span class="eyebrow">REFLECTION GUIDE / PREPARED CONTENT</span><h2>Go beyond<br><em>who was right.</em></h2><p>${esc(c.lesson)}</p><div class="reflection-rule"></div><h3>A question for your recommendation</h3><p>${esc(c.choices[state.choice].reflection)}</p><p class="small">This prompt follows your selected option. It is not an AI assessment of your reasoning.</p></aside></div></details>${state.activeCase?`<section class="agenda-reveal"><p class="eyebrow">AFTER THE DISCUSSION / PRIVATE INCENTIVES</p><h2>What was each person protecting?</h2><p>${esc(c.reveal)}</p><div>${c.people.map(p=>`<article><h3>${esc(p.name)}</h3><p>${esc(p.privateAim)}</p><small>Related claim evidence: ${esc(p.source)}</small></article>`).join('')}</div><p class="small">This reveals the authored simulation, not a diagnosis of real people. The coaching uses only public evidence and your answers; hidden incentives are not a hindsight test.</p></section>`:''}<div class="review-bottom"><div><p class="eyebrow">KEEP THE QUESTIONING GOING</p><h2>Different evidence.<br>Same curious mind.</h2><p>${esc(c.next)}</p></div><div>${button('Try another round '+arrow,'general','button dark')}${state.mode==='interview'?button('Back to my preparation path','path','text-button'):button('Prepare for a role →','jd','text-button')}</div></div>`;}
function activity(){return `${header('YOUR ACTIVITY','Small rounds.<br><em>Useful perspective.</em>','A simple record of completed previews in this tab. It clears on refresh; there is no account or long-term skills assessment yet.')}<section class="surface activity">${state.history.length?state.history.map((h,i)=>`<article><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><p class="eyebrow">${esc(h.mode==='interview'?'INTERVIEW PREPARATION':'GENERAL PRACTICE')}</p><h2>${esc(h.skill)}</h2><p>${h.questions} ${h.caseId==='council'?'messages':'questions'} · ${h.records} records opened · ${esc(h.decision)}</p></div><span class="outline-badge">Completed preview</span></article>`).join(''):`<div class="empty-state"><span class="empty-symbol">↗</span><h2>Your first round starts here.</h2><p>Complete a practice preview to see your activity.</p>${button('Explore practice','general','button dark')}</div>`}</section>`;}
function council(){return councilMarkup(councilView(state.council),state.councilOrigin,councilChatMarkup(state.council,state.councilChat));}
function sendCouncilMessage(){
 if(state.view!=='council'||!state.councilChat)return;
 state.councilChat=submitCouncilMessage(state.council,state.councilChat,state.councilChat.draft);
 render();const log=document.querySelector('.chat-log');log?.scrollTo?.({top:log.scrollHeight});
 document.querySelector(state.councilChat.pending?'#chat-response':'.chat-exchange:last-child')?.focus();
}
app.addEventListener('submit',e=>{if(e.target.id==='council-chat-form'){e.preventDefault();sendCouncilMessage();}});
app.addEventListener('keydown',e=>{if(e.target.id==='council-message'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();sendCouncilMessage();}});
function render(){app.innerHTML=nav()+`<main id="main" class="${state.view==='home'?'home-main':'inner-main'}">${({home,general,jd,path,session,review,activity,council}[state.view]||home)()}</main>`+footer();document.title=state.view==='home'?'Stakewolf — Good judgment. Practised.':`Stakewolf — ${state.view==='jd'?'Prepare for your role':state.view==='session'?'Practice room':state.view==='path'?'Your preparation path':state.view==='review'?'Your practice trace':state.view==='activity'?'Your activity':state.view==='council'?'Your council':'General practice'}`;wireRecords();}
function wireRecords(){document.querySelectorAll('[data-record]').forEach(el=>el.addEventListener('toggle',()=>{if(el.isConnected&&state.view==='session'&&(state.stage==='investigate'||state.stage==='challenge')&&el.open){state.opened.add(el.dataset.record);const count=document.querySelector('.evidence-rail .section-line span');if(count)count.textContent=`${state.opened.size}/${currentCase().evidence.length} OPENED`;}}));}
function start(id,generated=null){state.caseId=id;state.activeCase=generated;state.activeSkill=generated?id:null;state.opened=new Set();state.asked=new Set();state.stage='investigate';state.choice=null;state.firstChoice=null;state.note='';state.revision='';state.openedBefore=[];state.attempt=null;state.rehearsal='';state.rehearsalResult=null;go('session');}
app.addEventListener('input',e=>{if(e.target.id==='council-message'&&state.councilChat){state.councilChat.draft=e.target.value;if(state.councilChat.pending){const caret=e.target.selectionStart;state.councilChat={...state.councilChat,pending:null,notice:'Interpretation cleared because you edited your message.'};render();const input=document.querySelector('#council-message');input?.focus();if(Number.isInteger(caret))input?.setSelectionRange?.(caret,caret);}}if(e.target.id==='jd-text'){state.jd=e.target.value;document.querySelector('#build-path').disabled=!state.jd.trim();}if(e.target.id==='rehearsal-answer')state.rehearsal=e.target.value;if(e.target.id==='reasoning')state[state.stage==='challenge'?'revision':'note']=e.target.value;});
app.addEventListener('change',e=>{if(e.target.id==='council-speaker'&&state.view==='council'&&councilView(state.council).stakeholders.some(p=>p.id===e.target.value)){state.councilChat={...state.councilChat,speakerId:e.target.value,pending:null,notice:''};render();document.querySelector('#council-message')?.focus();return;}if(e.target.id==='level')state.level=e.target.value;if(e.target.id==='role-select'){state.role=e.target.value;render();document.querySelector('#role-select').focus();}if(e.target.name==='skill'){const id=e.target.value;state.selected=e.target.checked?[...state.selected,id]:state.selected.filter(x=>x!==id);render();document.querySelector(`[name="skill"][value="${id}"]`)?.focus();}if(e.target.name==='decision'){state.choice=Number(e.target.value);document.querySelectorAll('.choice').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked));document.querySelector('#decision-submit').disabled=false;}});
app.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
if(a==='start-council'){
  if(!councilTopics.some(t=>t.id===el.dataset.topic))return;
  state.councilOrigin=state.view==='path'?'interview':'general';
  state.mode=state.councilOrigin;
  state.council=createCouncil(el.dataset.topic);state.councilChat=newCouncilChat(state.council);return go('council');
}
if(a==='talk-confirm'||a==='talk-cancel'){
 if(state.view!=='council'||!state.councilChat)return;
 if(a==='talk-confirm'){const result=confirmCouncilMessage(state.council,state.councilChat);state.council=result.state;state.councilChat=result.chat;}
 else state.councilChat={...state.councilChat,pending:null,notice:'Interpretation dismissed. No changes made.'};
 render();const log=document.querySelector('.chat-log');log?.scrollTo?.({top:log.scrollHeight});document.querySelector('#chat-response')?.focus();return;
}
if(a.startsWith('council-')){
  if(state.view!=='council'||!state.council)return;
  const type=a.slice(8),before=state.council.phase;
  const scroll=window.scrollY;
  const next=councilAct(state.council,{type,recordId:el.dataset.id,commitmentId:el.dataset.id,proposalId:el.dataset.id,workId:el.dataset.id});
  state.council=next;
  if(type==='replay'){state.councilChat=newCouncilChat(next);}else if(next!==undefined&&state.councilChat?.pending){state.councilChat={...state.councilChat,pending:null,notice:'Previous interpretation cleared. Ask again using the updated council.'};}
  if(next.phase!==before){
    if(next.phase==='debrief'){
      const view=councilView(next);
      state.history.push({mode:state.councilOrigin,caseId:'council',questions:state.councilChat?.total||0,records:view.records.filter(r=>r.opened).length,skill:view.title,decision:view.debrief.summary});
    }
    return go('council');
  }
  render();window.scrollTo(0,scroll);
  const view=councilView(next);
  const target=view.error?'#council-status':type==='investigate'?`[data-opened="${el.dataset.id}"]`:`[data-action="${a}"][data-id="${el.dataset.id}"]`;
  document.querySelector(target)?.focus({preventScroll:true});return;
}
if(a==='rehearse'&&state.view==='review'&&state.attempt){state.rehearsalResult=state.rehearsal;render();document.querySelector('#rehearsal-feedback')?.focus();return;}
if(a==='reset-rehearsal'&&state.view==='review'){state.rehearsal='';state.rehearsalResult=null;render();document.querySelector('#rehearsal-answer')?.focus();return;}
if(a==='home'||a==='activity')return go(a);
if(a==='general'){state.mode='general';return go('general');}
if(a==='jd'){state.mode='interview';return go('jd');}
if(a==='sample'){state.jd=el.dataset.role==='platform'?'Technical Product Manager — Platform\nOwn API integrations, reliability and service dependencies. Prioritise the roadmap with engineering capacity and customer commitments. Define success metrics and explain trade-offs.':profiles[el.dataset.role].jd;state.role=el.dataset.role;render();document.querySelector('#jd-text').focus();return;}
if(a==='clear-jd'){state.jd='';state.matches=[];state.analysis=null;state.selected=[];render();document.querySelector('#jd-text').focus();return;}
if(a==='build-path'){if(!state.jd.trim())return;state.analysis=analyzeJD(state.jd);state.selected=state.analysis.matches.slice(0,3).map(x=>x.id);state.role=state.analysis.roles[0]?.id||'general';return go('path');}
if(a==='path')return go('path');
if(a==='start')return start(el.dataset.case);
if(a==='start-adaptive'){const id=el.dataset.skill;if(!state.selected.includes(id))return;state.mode='interview';return start(id,makeCase(id,{level:state.level,role:state.role}));}
if(a==='back-practice')return go(state.mode==='interview'?'path':'general');
if(a==='ask'){if(state.view!=='session'||state.stage!=='investigate')return;if(state.activeCase&&state.asked.size>=2)return;captureOpened();const index=Number(el.dataset.index);state.asked.add(index);const scroll=window.scrollY;render();window.scrollTo(0,scroll);document.querySelector(`[data-reply="${index}"]`)?.focus({preventScroll:true});return;}
if(a==='commit'&&state.view==='session'&&state.stage==='investigate'&&state.choice!==null){captureOpened();state.openedBefore=[...state.opened];state.firstChoice=state.choice;state.stage='challenge';return go('session');}
if(a==='finish'&&state.view==='session'&&state.stage==='challenge'&&state.choice!==null){captureOpened();state.attempt={note:state.note,revision:state.revision,firstChoice:state.firstChoice,choice:state.choice,openedBefore:[...state.openedBefore],openedAfter:[...state.opened],asked:[...state.asked]};state.stage='complete';state.history.push({mode:state.mode,caseId:state.caseId,questions:state.asked.size,records:state.opened.size,skill:currentCase().skill,decision:currentCase().choices[state.choice].title});return go('review');}
});
render();
